<?php
if (!defined('ABSPATH')) exit;
function gim_recalculate_outcome($provider_id,$service){ global $wpdb; $jobs=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".gim_table('jobs')." WHERE provider_id=%d AND service_slug=%s AND status='completed'",$provider_id,$service)); $n=count($jobs); if(!$n){$score=50;$conf=0;$level='INSUFFICIENT';$signals=[];}else{ $ratings=[];$staPass=0;$resolvedBad=0; foreach($jobs as $j){$r=$wpdb->get_var($wpdb->prepare("SELECT AVG(rating) FROM ".gim_table('reviews')." WHERE job_id=%d AND status='published'",$j->id)); if($r)$ratings[]=(float)$r; $sta=$wpdb->get_var($wpdb->prepare('SELECT decision FROM '.gim_table('assurance_runs').' WHERE job_id=%d ORDER BY id DESC LIMIT 1',$j->id)); if($sta==='PASS')$staPass++; $d=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('disputes')." WHERE job_id=%d AND status IN ('resolved','closed') AND resolution IN ('FULL_REFUND','PARTIAL_REFUND')",$j->id)); $resolvedBad+=(int)$d; }
 $reviewRaw=$ratings?array_sum($ratings)/count($ratings)*20:50; $reviewScore=(($reviewRaw*count($ratings))+(50*5))/(count($ratings)+5); $staScore=$n?($staPass/$n)*100:50; $disp=max(0,100-($resolvedBad/$n)*100); $score=round(.35*$staScore+.25*$disp+.40*$reviewScore,2); $conf=min(100,round($n/10*100)); $level=$n<3?'LOW':($n<7?'MEDIUM':'HIGH'); $signals=['sta'=>$staScore,'resolved_outcomes'=>$disp,'reviews'=>$reviewScore]; }
 $wpdb->insert(gim_table('outcome_runs'),['provider_id'=>$provider_id,'service_slug'=>$service,'engine_version'=>'gim-oi-v1','outcome_score'=>$score,'confidence_score'=>$conf,'confidence_level'=>$level,'sample_size'=>$n,'signals_json'=>gim_json($signals),'created_at'=>gim_now()]); return ['score'=>$score,'confidence'=>$conf,'level'=>$level,'sample_size'=>$n]; }
